//! Full-ISA vector replay against the independent MC6800 oracle.
//!
//! Replays the same fixtures the ai_hw_engineer RTL testbench consumes
//! (`../oracle/isa`, generated by design/motorola_6800/scripts/
//! make_isa_vectors.py): the 64K image, one boundary record
//! (pc a b ix sp cc) per opcode fetch, clock-keyed external IRQ/NMI
//! triggers, the $E000 control port (0 = IRQ low, 1 = IRQ high, 2 = NMI
//! pulse, $AA = done) and the final-memory compare.

mod common;

use common::{load_mem, load_vectors, oracle_dir, Mem, Trigger};
use motorola_6800::Mc6800;

#[test]
fn full_isa_vector_replay() {
    let dir = oracle_dir().join("isa");
    let image = load_mem(&dir.join("mem.hex"));
    let gold = load_mem(&dir.join("gold_mem.hex"));
    let records = load_vectors(&dir.join("vectors.hex"));
    let mut triggers = Trigger::load(&dir.join("triggers.hex"));

    let mut cpu = Mc6800::new();
    let mut bus = Mem::new(&image);
    cpu.reset(&mut bus);

    let mut vidx = 0usize;
    let mut done = false;
    let mut ticks = 0u64;
    while !done {
        let tick = cpu.tick(&mut bus);
        ticks += 1;
        assert!(ticks < 2_000_000, "replay did not finish in time");

        // Trigger engine, one clock edge per tick.
        for t in triggers.iter_mut() {
            if let Some(action) = t.tick(tick.sync, tick.fetch_pc) {
                match action {
                    0 => cpu.set_irq_level(true),
                    1 => cpu.set_irq_level(false),
                    2 => cpu.pulse_nmi(),
                    other => panic!("bad trigger action {other}"),
                }
            }
        }

        // $E000 control port (mirrors the RTL testbench's io_write).
        if let Some((0xE000, val)) = tick.write {
            match val {
                0x00 => cpu.set_irq_level(true),
                0x01 => cpu.set_irq_level(false),
                0x02 => cpu.pulse_nmi(),
                0xAA => done = true,
                _ => {}
            }
        }

        // Boundary compare on every opcode fetch, pre-edge state.
        if tick.sync && !done {
            let rec = records
                .get(vidx)
                .unwrap_or_else(|| panic!("extra fetch beyond vector file at {:04X}", tick.pre.pc));
            let pre = tick.pre;
            let bad = pre.pc != rec[0]
                || u16::from(pre.a) != rec[1]
                || u16::from(pre.b) != rec[2]
                || pre.ix != rec[3]
                || pre.sp != rec[4]
                || u16::from(pre.cc) != rec[5];
            if bad {
                panic!(
                    "boundary mismatch at vector {vidx}: got pc={:04X} a={:02X} b={:02X} ix={:04X} sp={:04X} cc={:02X}, want {:04X} {:02X} {:02X} {:04X} {:04X} {:02X}",
                    pre.pc, pre.a, pre.b, pre.ix, pre.sp, pre.cc,
                    rec[0], rec[1], rec[2], rec[3], rec[4], rec[5]
                );
            }
            vidx += 1;
        }
    }

    assert_eq!(
        vidx,
        records.len(),
        "done before consuming all {} boundary records (consumed {vidx})",
        records.len()
    );

    let mdiff: Vec<usize> = (0..65536).filter(|&i| bus.mem[i] != gold[i]).collect();
    assert!(
        mdiff.is_empty(),
        "final memory differs from oracle gold at {} addresses, first: {:04X} got {:02X} want {:02X}",
        mdiff.len(),
        mdiff[0],
        bus.mem[mdiff[0]],
        gold[mdiff[0]]
    );

    println!(
        "full-ISA replay PASSED: {} boundary checks, {} clocks, final pc {:04X}",
        vidx,
        ticks,
        cpu.regs().pc
    );
}

/// The $E000 control-port effects must come from bus writes the core
/// actually performs (the test bus sees every write cycle).
#[test]
fn control_port_write_visible_on_tick() {
    // STAA $E000 ($B7 E0 00) with A=$AA, then BRA *.
    let mut image = vec![0u8; 65536];
    image[0xFFFE] = 0x01;
    image[0xFFFF] = 0x00;
    image[0x0100] = 0x86;
    image[0x0101] = 0xAA;
    image[0x0102] = 0xB7;
    image[0x0103] = 0xE0;
    image[0x0104] = 0x00;
    image[0x0105] = 0x20;
    image[0x0106] = 0xFE;

    let mut cpu = Mc6800::new();
    let mut bus = Mem::new(&image);
    cpu.reset(&mut bus);
    let mut saw_write = None;
    for _ in 0..64 {
        let tick = cpu.tick(&mut bus);
        if tick.write == Some((0xE000, 0xAA)) {
            saw_write = Some(true);
            break;
        }
    }
    assert_eq!(saw_write, Some(true), "$AA never stored to $E000");
}
